#define TEX_WIDTH 64
#define TEX_HEIGHT 64
#define TEX_CHANNEL_COUNT 3
#define TEX_FILENAME "texture.raw"
#define TEX_FILESIZE sizeof(uint8_t) * 2 + sizeof(uint8_t) * TEX_WIDTH * TEX_HEIGHT * TEX_CHANNEL_COUNT

int main(int argc, char *argv[]) {
	uint8_t *pBuffer = malloc(TEX_FILESIZE);
	srand(time(NULL));
	pBuffer[0] = TEX_WIDTH;
	pBuffer[1] = TEX_HEIGHT;
	for (unsigned int i = 2; i < TEX_WIDTH * TEX_HEIGHT * TEX_CHANNEL_COUNT; ++i) {
		pBuffer[i] = rand() % 255;
	}
	FILE *pFile = fopen(TEX_FILENAME, "wb");
	fwrite(pBuffer, TEX_FILESIZE, 1, pFile);
	fclose(pFile);
}
