      left: `${position.x}px`,
      top: `${position.y}px`,
    }}
  />
);

const GameMain = () => {
  const [playerPosition, setPlayerPosition] = useState({ x: VIEW_WIDTH / 2, y: 300 });
  const [isGrounded, setIsGrounded] = useState(false)
  const [platforms, setPlatforms] = useState([
    { width: PLATFORM_WIDTH, height: PLATFORM_HEIGHT, top: 450, left: VIEW_WIDTH / 2 - PLATFORM_WIDTH / 2 },
  ]);

  const playerVelocityRef = useRef({ x: 0, y: 0 });
  const keysPressed = useRef({ left: false, right: false, up: false });
  const requestIdRef = useRef(null);

  const generatePlatform = (direction) => {
    const lastPlatform = platforms[platforms.length - 1];
    const newPlatformTop = Math.floor(Math.random() * (VIEW_HEIGHT - PLATFORM_HEIGHT - 100)) + 100;

    const newPlatform = {
      width: PLATFORM_WIDTH,
      height: PLATFORM_HEIGHT,
      top: newPlatformTop,
      left:
        direction === "right"
          ? lastPlatform.left + lastPlatform.width + Math.random() * 100
          : lastPlatform.left - PLATFORM_WIDTH - Math.random() * 100,
    };

    setPlatforms(currentPlatforms => [...currentPlatforms, newPlatform]);
  };

  // Detecting platform collision and updating position and velocity accordingly
  const handlePhysics = (timeDelta) => {
    // Apply horizontal movement
    const { left, right, up } = keysPressed.current;
    let velocityX =
      left && !right ? -MOVE_SPEED * timeDelta :
      right && !left ? MOVE_SPEED * timeDelta :
      0;

    // Apply gravity and vertical movement
    let velocityY = playerVelocityRef.current.y + GRAVITY * timeDelta;
    if (up) {
      velocityY = JUMP_STRENGTH;
      keysPressed.current.up = false;
    }

    let newPlayerPosition = {
      x: playerPosition.x + velocityX,
      y: Math.max(playerPosition.y + velocityY, 0),
    };

    // Check for platform collisions
    platforms.forEach((platform) => {
      if (
        newPlayerPosition.x < platform.left + platform.width &&
        newPlayerPosition.x + PLAYER_WIDTH > platform.left &&
        newPlayerPosition.y < platform.top + platform.height &&
        newPlayerPosition.y + PLAYER_HEIGHT > platform.top
      ) {
        if (playerPosition.y <= platform.top && velocityY > 0) {
          newPlayerPosition.y = platform.top - PLAYER_HEIGHT;
          velocityY = 0;
        }
      }
    });

    playerVelocityRef.current.y = velocityY;

    // Platform generation logic
    if (newPlayerPosition.x > VIEW_WIDTH - HORIZONTAL_MARGIN && !keysPressed.current.left) {
      generatePlatform("right");
    } else if (newPlayerPosition.x < HORIZONTAL_MARGIN && !keysPressed.current.right) {
      generatePlatform("left");
    }

    // Keep the player horizontally centered in the viewport
    let playerX = VIEW_WIDTH / 2;
    let offset = VIEW_WIDTH / 2 - newPlayerPosition.x;

    // Keep platforms and player position in sync
    setPlatforms(currentPlatforms =>
      currentPlatforms.map(platform => ({
        ...platform,
        left: platform.left + offset,
      }))
    );

    setPlayerPosition({ x: playerX, y: newPlayerPosition.y });
  };

  const updateGame = (timestamp) => {
    const now = Date.now();
    const deltaTime = (now - (requestIdRef.current || now)) / 1000; // Convert to seconds
    requestIdRef.current = now;

    let velocityY = playerVelocity.y + GRAVITY * deltaTime;
    let velocityX = 0;
    let newPlayerPosition = { ...playerPosition };

    handlePhysics(deltaTime);

    requestAnimationFrame(updateGame);
  };

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === "ArrowLeft") keysPressed.current.left = true;
      if (event.key === "ArrowRight") keysPressed.current.right = true;
      if (event.key === "ArrowUp" && isGrounded) keysPressed.current.up = true;
    };

    const handleKeyUp = (event) => {
      if (event.key === "ArrowLeft") keysPressed.current.left = false;
      if (event.key === "ArrowRight") keysPressed.current.right = false;
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);

    requestIdRef.current = requestAnimationFrame(updateGame);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
      cancelAnimationFrame(requestIdRef.current);
    };
  }, []); // Removed dependencies to prevent re-initialization

  return (
