import React, { useState, useEffect, useRef } from "react";

// Constants for gravity, jumping, and movement
const GRAVITY = 1500;
const JUMP_STRENGTH = -600;
const MOVE_SPEED = 650;
const PLATFORM_GENERATION_THRESHOLD = 200; // The buffer distance at which to generate new platforms
const PLAYER_WIDTH = 50;
const PLAYER_HEIGHT = 50;
const PLATFORM_WIDTH = 400;
const PLATFORM_HEIGHT = 20;
const VIEW_WIDTH = 800;
const VIEW_HEIGHT = 600;

// Platform component
const Platform = ({ width, height, top, left }) => (
  <div
    style={{
      position: "absolute",
      width: `${width}px`,
      height: `${height}px`,
      backgroundColor: "brown",
      left: `${left}px`,
      top: `${top}px`,
    }}
  />
);

// Player component
const Player = ({ position }) => (
  <div
    style={{
      position: "absolute",
      width: `${PLAYER_WIDTH}px`,
      height: `${PLAYER_HEIGHT}px`,
      backgroundColor: "blue",
      left: `${position.x}px`,
      top: `${position.y}px`,
    }}
  />
);
function GameMain() {
    const [playerPosition, setPlayerPosition] = useState({ x: VIEW_WIDTH / 2, y: 300 });
    const [isGrounded, setIsGrounded] = useState(false);
    const [platforms, setPlatforms] = useState([
      { width: PLATFORM_WIDTH, height: PLATFORM_HEIGHT, top: VIEW_HEIGHT - 100, left: VIEW_WIDTH / 2 - PLATFORM_WIDTH / 2 },
    ]);

    const playerVelocityRef = useRef({ x: 0, y: 0 });
    const keysPressed = useRef({ left: false, right: false, up: false });
    const requestIdRef = useRef(null);
    const lastTimestampRef = useRef(0);

    const generatePlatform = (direction) => {
      // Generate a new platform offscreen to the right or left based on the direction
      const lastPlatform = platforms[platforms.length - 1];
      const newPlatformTop = Math.random() * (VIEW_HEIGHT - 3 * PLATFORM_HEIGHT);

      if (direction === "right") {
        const newPlatform = {
          width: PLATFORM_WIDTH,
          height: PLATFORM_HEIGHT,
          top: newPlatformTop,
          left: lastPlatform.left + lastPlatform.width + Math.random() * 100 + PLATFORM_WIDTH,
        };
        setPlatforms(ps => [...ps, newPlatform]);
      } else if (direction === "left" && platforms[0].left > 0) {
        const newPlatform = {
          width: PLATFORM_WIDTH,
          height: PLATFORM_HEIGHT,
          top: newPlatformTop,
          left: platforms[0].left - PLATFORM_WIDTH - Math.random() * 100,
        };
        setPlatforms(ps => [newPlatform, ...ps]);
      }
    };

    const updatePhysics = (deltaTime) => {
      let velocity = { ...playerVelocityRef.current };
      let pos = { ...playerPosition };

      if (keysPressed.current.left) pos.x -= MOVE_SPEED * deltaTime;
      if (keysPressed.current.right) pos.x += MOVE_SPEED * deltaTime;

      // Vertical physics
      velocity.y += GRAVITY * deltaTime;
      pos.y += velocity.y * deltaTime;

      // Collision detection
      let wasGrounded = isGrounded;
      setIsGrounded(false);

      platforms.forEach(platform => {
        if (
          pos.x < platform.left + platform.width &&
          pos.x + PLAYER_WIDTH > platform.left &&
          pos.y < platform.top + platform.height &&
          pos.y + PLAYER_HEIGHT > platform.top
        ) {
          // Collision detected!
          if (wasGrounded && velocity.y > 0) {
            // Player was descending
            pos.y = platform.top - PLAYER_HEIGHT;
            velocity.y = 0;
            setIsGrounded(true);
          }
        }
      });

      // Jumping
      if (keysPressed.current.up && isGrounded) {
        velocity.y = JUMP_STRENGTH;
        keysPressed.current.up = false; // Prevent additional jumps while already jumping
      }

      // Update position and velocity
      setPlayerPosition(pos);
      playerVelocityRef.current = velocity;

      // Generate new platforms when necessary
      if (pos.x < PLATFORM_GENERATION_THRESHOLD) {
        generatePlatform("left");
      } else if (pos.x > VIEW_WIDTH - PLATFORM_GENERATION_THRESHOLD) {
        generatePlatform("right");
      }
    };

    const gameLoop = (timestamp) => {
      const deltaTime = (timestamp - lastTimestampRef.current) / 1000;
      lastTimestampRef.current = timestamp;

      updatePhysics(deltaTime);

      requestIdRef.current = requestAnimationFrame(gameLoop);
    };

    useEffect(() => {
      const handleKeyDown = (event) => {
        if (event.key === "ArrowLeft") keysPressed.current.left = true;
        if (event.key === "ArrowRight") keysPressed.current.right = true;
        if (event.key === "ArrowUp" && isGrounded) keysPressed.current.up = true;
      };

      const handleKeyUp = (event) => {
        if (event.key === "ArrowLeft") keysPressed.current.left = false;
        if (event.key === "ArrowRight") keysPressed.current.right = false;
        // The up key is managed within updatePhysics
      };

      window.addEventListener("keydown", handleKeyDown);
      window.addEventListener("keyup", handleKeyUp);

      requestIdRef.current = requestAnimationFrame(gameLoop);

      return () => {
        window.removeEventListener("keydown", handleKeyDown);
        window.removeEventListener("keyup", handleKeyUp);
        cancelAnimationFrame(requestIdRef.current);
      };
    }, []);

    return (
      <div style={{ position: "relative", width: VIEW_WIDTH, height: VIEW_HEIGHT, overflow: "hidden" }}>
        <Player position={playerPosition} />
        {platforms.map((platform, index) => (
          <Platform key={index} {...platform} />
        ))}
      </div>
    );
  }

  export default GameMain;

