		player_lifebar.value = health
	else:
		print("Warning: No player lifebar UI found in the scene.")

func set_health(value: int) -> void:
	health = clamp(value, 0, MAX_HEALTH)
	update_health_ui()
	emit_signal("health_changed", health)

func update_health_ui() -> void:
	if player_lifebar:
		player_lifebar.value = health

func take_damage(damage: int) -> void:
	set_health(health - damage)

func heal(amount: int) -> void:
	set_health(health + amount)

# Define a generic move function with a placeholder parameter type.
func move(movement_input) -> void:
	pass  # To be implemented by child classes (2D / 3D)

# Use a generic attack method.
func attack() -> void:
	pass  # To be implemented by child classes (2D / 3D)

