                                               question=question, 
                                               answer=answer, 
                                               feedback=feedback,
                                               option1=option1,
                                               option2=option2,
                                               option3=option3,
                                               option4=option4,
                                               option5=option5,
                                               appropriateAnswer=appropriateAnswer,
                                               comments=comments,
                                               citation_file_names= citation_file_names)
        return jsonify({"feedback": "Feedback successfully stored"}), 200

    except Exception as e:
