   public void setStartSpecFromTank() {
   }

   public void update() {
      this.emc = Double.valueOf(this.emc.doubleValue() + 0.2D);
      if (this.emc.doubleValue() <= 0.1D) {
         this.t = null;
         this.currFlameTimer = null;
         this.t = new Timer();
         this.currFlameTimer = new FlamethrowerTimer();
         this.t.schedule(this.currFlameTimer, 0L, 1000L);
      }
      sendChangeTemperature(TemperatureCalc.getTemperature(this.emc.doubleValue()));
   }

   private void sendChangeTemperature(double value) {
      this.bfModel.sendToAllPlayers(Type.BATTLE, new String[]{"change_temperature_tank", this.tank.id, String.valueOf(value)});
   }

   class FlamethrowerTimer extends TimerTask {
      public void run() {
         FireEffectModel.this.emc = Double.valueOf(FireEffectModel.this.emc.doubleValue() - 0.03D);
         try {
            // FireEffectModel.this.bfModel.tanksKillModel.damageTank(FireEffectModel.this.bfModel, FireEffectModel.this.bfModel, FireEffectModel.this.fg * 0.1F, true, false);
            FireEffectModel.this.sendChangeTemperature(FireEffectModel.this.emc.doubleValue());
            if (FireEffectModel.this.emc.doubleValue() <= 0.0D)
               cancel();
         } catch (NullPointerException e) {
            cancel();
         }
      }
   }
