template <typename T>
int Compare(date x, date y)
{
    if(x > y) 
    {
        return 1;
    }
    if (x < y) 
    {
        return -1;
    }
    if (x == y) 
    {
        return 0;
    }
}

student FindYoungestStudent(students_arr array) 
{
    int index = 0;
    for (int i = 1; i < array.size; i++)
    {
        if (Compare(array.arr[i].Birthday, array.arr[index].Birthday) == -1) 
        {
            index = i;
        }
