import { AppDispatch } from "..";
import axios from "axios";
import { categorySaleSlice } from "../slices/categorySaleSlice";
import { categorySaleListShema } from "../../models/categorySaleListShema";
// Функция fetchCategorySale принимает jwt в качестве токена аутентификации
export const fetchCategorySale = (jwt: string) => {
  //при использовании  async (dispatch: AppDispatch) . 
  // В данном случае, это означает, что функция  fetchCategorySale  возвращает асинхронную функцию,
  // которая принимает параметр  dispatch  с типом  AppDispatch .
  return async (dispatch: AppDispatch) => {
    // Формируем заголовок запроса с авторизационным токеном
    let header = { Authorization: `Bearer ${jwt}` };
    try {
      // Диспатчим действие fetching для установки флага загрузки в true
      dispatch(categorySaleSlice.actions.fetching());
      const url = `${window.location.origin}/interaction/api/0.1/get_category`;
      // Выполняем GET-запрос с использованием axios и сохраняем результат в response_category
      const response_category = axios.get<categorySaleListShema>(url, {
        headers: header,
      });
      // Используем Promise.all для ожидания выполнения всех асинхронных запросов
      Promise.all([response_category]).then((responses) => {
        // Проверяем, есть ли ошибки в полученных ответах
        let isError = responses.some(
          (response) => response.data.return_code !== 0
        );
        // Если ошибок нет, обновляем состояние с помощью действия fetchSuccessCategorySale
        if (!isError) {
          dispatch(
            categorySaleSlice.actions.fetchSuccessCategorySale(
              responses[0].data.data
            )
          );
          // Устанавливаем флаг загрузки в false с помощью действия fetchSuccess
          dispatch(categorySaleSlice.actions.fetchSuccess());
        }
      });
    } catch (error) {
      // Если происходит ошибка при выполнении запроса, устанавливаем флаг ошибки в true
      dispatch(categorySaleSlice.actions.fetchingError());
    }
  };
};
import { PayloadAction, createSlice } from "@reduxjs/toolkit";
import { ICategorySaleListShema } from "../../models/categorySaleListShema";

// Определение типа начального состояния
export interface initialStateTypes {
  categorySale: ICategorySaleListShema[];
  loading: boolean;
  error: boolean;
}

// Начальное состояние
const initialState: initialStateTypes = {
  categorySale: [],
  loading: false,
  error: false,
};

// Создание среза (slice) для управления состоянием
export const categorySaleSlice = createSlice({
  name: "categorySale",
  initialState: initialState,
  reducers: {
    // Действие для начала загрузки данных
    fetching(state) {
      state.loading = true;
      state.error = false;
    },

    // Действие при успешной загрузке данных
    fetchSuccess(state) {
      state.loading = false;
    },

    // Действие при успешной загрузке данных категорий продаж
    fetchSuccessCategorySale(
      state,
      action: PayloadAction<ICategorySaleListShema[]>
    ) {
      state.categorySale = action.payload;
    },

    // Действие при ошибке загрузки данных
    fetchingError(state) {
      state.error = true;
    },
  },
});

// Экспорт редьюсера для использования в приложении
