        uemeas_interlb = parse_nodeb_mo_pars(enm_uemeas_interlb, EnmCli.UeMeasControl_ReportConfigEUtraInterFreqLb2[-1], 'Sub_EUtranCellFDD')
        uemeas_interlb_cleaned = clean_cell(uemeas_interlb)
