.helm/values.yaml  base-chart:
  defaultImagePullPolicy: IfNotPresent
  generic:
    serviceAccountName: "{{ .Release.Name }}"
    extraImagePullSecrets:
    - name: dockey
  deploymentsGeneral:
    terminationGracePeriodSeconds: 120
    envFrom:
      - secretRef:
          name: sec-widget-config

  serviceAccount:
    "{{ .Release.Name }}":
      labels: {}

  services:
    app:
      type: ClusterIP
      ports:
        http:
          port: 80
          targetPort: http
          protocol: TCP

  ingresses:
    http:
      annotations:
        kubernetes.io/ingress.class: nginx
        nginx.ingress.kubernetes.io/proxy-body-size: "128m"
        nginx.ingress.kubernetes.io/use-regex: "true"

  serviceMonitors:
    http:
      endpoints:
        http:
          path: /metrics
          interval: 15s

  deployments:
    app:
      strategy:
        type: RollingUpdate
        rollingUpdate:
          maxSurge: 5
          maxUnavailable: 5
      containers:
        app:
          securityContext:
            capabilities:
              add:
              - SYS_PTRACE
          ports:
            http:
              containerPort: 8080
              protocol: TCP
          resources:
            limits:
              cpu: 500m
              memory: 500Mi
            requests:
              cpu: 500m
              memory: 500Mi
          volumeMounts:
          - name: nginx-config
            mountPath: /etc/nginx/nginx.conf
            subPath: nginx.conf
          - name: nginx-config
            mountPath: /etc/nginx/mime.types
            subPath: mime-types
      volumes:
      - type: configMap
        name: nginx-config
        items:
        - key: nginx.conf
          path: nginx.conf
        - key: mime-types
          path: mime-types

  configMaps:
    nginx-config:
      data:
        nginx.conf: |
          pid /var/run/nginx.pid;
          worker_processes  auto;

          events {
            worker_connections  1024;
          }

          http {
            keepalive_timeout  65;
            include /etc/nginx/mime.types;
            default_type  application/octet-stream;
            gzip  on;
            gzip_types
              application/atom+xml
              application/geo+json
              application/javascript
              application/json
              application/ld+json
              application/manifest+json
              application/octet-stream
              application/rdf+xml
              application/rss+xml
