#include <iostream>
#include <vector>

struct Node {
  int data;
  Node* left;
  Node* right;

  Node(int value) : data(value), left(nullptr), right(nullptr) {}
};

struct BST {
  Node* top = nullptr;

  Node* insert(Node* root, int value) {
    if (root == nullptr) {
        return new Node(value);
    }
    if (value < root->data) {
      root->left = insert(root->left, value);
    } else if (value > root->data) {
      root->right = insert(root->right, value);
    }
    return root;
  }

  Node* findMin(Node* root) {
    while (root && root->left != nullptr) {
      root = root->left;
    }
    return root;
  }

  Node* pop(Node* root, int value) {
    if (root == nullptr) return nullptr;

    if (value < root->data) {
      root->left = pop(root->left, value);
    } else if (value > root->data) {
      root->right = pop(root->right, value);
    } else {
      if (root->left == nullptr) {
        Node* temp = root->right;
        delete root;
        return temp;
      } else if (root->right == nullptr) {
        Node* temp = root->left;
        delete root;
        return temp;
      }
      Node* temp = findMin(root->right);
      root->data = temp->data;
      root->right = pop(root->right, temp->data);
    }
    return root;
  }

  void inorder(Node* root) {
    if (root == nullptr) return;

    inorder(root->left);
    std::cout << root->data << " ";
    inorder(root->right);
  }

  void clear(Node* root) {
  if (root == nullptr) return;

  clear(root->left);
  clear(root->right);

  root->left = nullptr;
  root->right = nullptr;

  delete root;
  }

  void collect_vals(Node* root, std::vector<int>& elements) {
  if (!root) return;
  collect_vals(root->left, elements);
  elements.push_back(root->data);
  collect_vals(root->right, elements);
  }

  void merge(BST& other) {
    std::vector<int> elements;
    collect_vals(other.top, elements);

    for (int value : elements) {
      top = insert(top, value);
    }

    other.clear(other.top);
    other.top = nullptr;
  }
};


int main() {
  int n;
  std::cin >> n;
  std::string cmd;
  int acc;
  int id;
  BST arr[2];

  for (int i = 0; i < n; ++i) {
    std::cin >> cmd;
    if (cmd == "merge") {
      arr[0].merge(arr[1]);
      if (arr[0].top != nullptr) {
          arr[0].inorder(arr[0].top);
          std::cout << '\n';
      }
    } else {
      std::cin >> acc >> id;
      if (cmd == "buy") {
        arr[acc].top = arr[acc].insert(arr[acc].top, id);
      } else if (cmd == "sell") {
        arr[acc].top = arr[acc].pop(arr[acc].top, id);
      }
    }
  }
  return 0;
}



