from ENM_class import EnmCli
from parser_utils import parse_eutran_cells, parse_nodeb_pars, parse_nodeb_mo_pars, parse_fea, combine_fea, parse_cosector, clean_cell, clean_band, delete_region, parse_anr_rels
from Baseline import Baseline, compare
from file_write import stat, baseline_write
from collections import Counter
from dotenv import load_dotenv
from remove_old_files import remove_old_files
from mail import send_email
from upload_reports import upload_reports
# from datetime import datetime
load_dotenv('.env')

relation_reporting_map = {
    'UtranFreqRelation_prio3_base': ('UtranFreqRelation_prio3_par', Baseline.UtranFreqRelation_prio3_base),
    'UtranFreqRelation_prio4_base': ('UtranFreqRelation_prio4_par', Baseline.UtranFreqRelation_prio4_base),
    'GeranFreqGroupRelation_900_base': ('GeranFreqGroupRelation_900_par', Baseline.GeranFreqGroupRelation_900_base),
    'GeranFreqGroupRelation_1800_base': ('GeranFreqGroupRelation_1800_par', Baseline.GeranFreqGroupRelation_1800_base),
    'UeMeasControl_base': ('UeMeasControl_par', Baseline.UeMeasControl_base),

}

nodeb_children_map = {
    'ENodeBFunction_node': ('ENodeBFunction_par', Baseline.ENodeBFunction_node),
    'AnrFunction_node': ('AnrFunction_par', Baseline.AnrFunction_node),
    'AnrFunctionEUtran_node': ('AnrFunctionEUtran_par', Baseline.AnrFunctionEUtran_node),
}

def enm_main(mo_type, enm):

    if mo_type == 'BbuENodeBFunctionFea_base':
        enm_bbu_feature = EnmCli.execute_cli_command('BBU_ENodeBFunction_fea', enm)
        bbu_feature_sort = parse_fea(enm_bbu_feature)
        bbu_features = combine_fea(bbu_feature_sort, len(EnmCli.BbuENodeBFunctionFea))
        if bbu_features:
            return compare(bbu_features, Baseline.BbuENodeBFunctionFea_base)
    elif mo_type == 'DusENodeBFunctionFea_base':
        enm_dus_feature = EnmCli.execute_cli_command('DUS_ENodeBFunction_fea', enm)
        dus_feature_sort = parse_fea(enm_dus_feature)
        dus_features = combine_fea(dus_feature_sort, len(EnmCli.DusENodeBFunctionFea))
        if dus_features:
            return compare(dus_features, Baseline.DusENodeBFunctionFea_base)
    elif mo_type == 'QciProfilePredefined_traffic_base':
        enm_qci_traffic = EnmCli.execute_cli_command('QciProfilePredefined_9_par', enm) + \
                          EnmCli.execute_cli_command('QciProfilePredefined_7_par', enm)
        qci_traffic = parse_nodeb_mo_pars(enm_qci_traffic, EnmCli.QciProfilePredefined[-1], 'Sub_QciProfilePredefined')
        if qci_traffic:
            return compare(qci_traffic, Baseline.QciProfilePredefined_traffic_base)
    elif mo_type == 'ReportConfigEUtraInterFreqLb_800_base':
        enm_uemeas_interlb = EnmCli.execute_cli_command('ReportConfigEUtraInterFreqLb_par1', enm)
        uemeas_interlb = parse_nodeb_mo_pars(enm_uemeas_interlb, EnmCli.ReportConfigEUtraInterFreqLb1[-1],'Sub_EUtranCellFDD')
        uemeas_interlb_cleaned = clean_cell(uemeas_interlb)
        uemeas_interlb_cleaned_800 = clean_band(uemeas_interlb_cleaned, '800')
        if uemeas_interlb_cleaned_800:
            return compare(uemeas_interlb_cleaned_800, Baseline.ReportConfigEUtraInterFreqLb_800_base)
    elif mo_type == 'ReportConfigEUtraInterFreqLb_2100_base':
        enm_uemeas_interlb = EnmCli.execute_cli_command('ReportConfigEUtraInterFreqLb_par1', enm)
        uemeas_interlb = parse_nodeb_mo_pars(enm_uemeas_interlb, EnmCli.ReportConfigEUtraInterFreqLb1[-1],'Sub_EUtranCellFDD')
        uemeas_interlb_cleaned = clean_cell(uemeas_interlb)
        uemeas_interlb_cleaned_2100 = clean_band(uemeas_interlb_cleaned, '2100')
        if uemeas_interlb_cleaned_2100:
            return compare(uemeas_interlb_cleaned_2100, Baseline.ReportConfigEUtraInterFreqLb_2100_base)
    elif mo_type == 'EUtranCellRelationCosite_base':
        enm_cellrel_old = EnmCli.execute_cli_command('EUtranCellRelationCosite_par_old', enm)
        enm_cellrel_new = EnmCli.execute_cli_command('EUtranCellRelationCosite_par_new', enm)
        cellrel = parse_nodeb_mo_pars(enm_cellrel_old + enm_cellrel_new, EnmCli.EUtranCellRelationCosite[-1], 'Sub_EUtranCellFDD')
        cosite_cellrel_cleaned = clean_cell(cellrel)
        if cosite_cellrel_cleaned:
