#include <stdio.h>
#include <stdlib.h>


struct node {
    int num;    // numerator
    int den;    // denominator
    struct node* next;  // pointer to next node
};

// new Farey node and link it to next node
struct node* makeFareyNode(int num, int den, struct node* next) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE); // just in casies
    }
    new_node->num = num;
    new_node->den = den;
    new_node->next = next;
    return new_node;
}

// insert a node after a given node in linked list
void insertAfter(struct node* prev_node, int num, int den) {
    struct node* new_node = makeFareyNode(num, den, prev_node->next);
    prev_node->next = new_node;
}

// free linked list
void freeList(struct node* head) {
    struct node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// print linked list
void printList(struct node* node) {
    printf("(");
    while (node != NULL) {
        printf("%d/%d", node->num, node->den);
        node = node->next;
        if (node != NULL) {
            printf(", ");
        }
    }
    printf(")\n");
}

// sequence for the specified level
void outputFareySequence(int level) {
    struct node* head = makeFareyNode(0, 1, NULL);
    head->next = makeFareyNode(1, 1, NULL);

    for (int n = 1; n <= level; ++n) {
        struct node *current = head, *next = current->next;

        if (n > 1) {
            while (next) {
                if (current->den + next->den == n) {
                    insertAfter(current, current->num + next->num, n);
                    current = current->next;
                }
                current = next;
                next = next->next;
            }
        }


        printList(head);
    }


    freeList(head);
}

int main() {
    int level;
    printf("Enter the level of the Farey sequence: ");
    scanf("%d", &level);

    outputFareySequence(level);

    return 0;
}

