<script>
    function copyPromoCode(identifiant, url) {
        var promoCode = document.getElementById("promoCode-" + identifiant).innerText;
        var dummyInput = document.createElement("input");
        document.body.appendChild(dummyInput);
        dummyInput.setAttribute('value', promoCode);
        dummyInput.select();
        document.execCommand('copy');
        document.body.removeChild(dummyInput);
        var newWindow = window.open();
        newWindow.location.href = url;
        alert("Code promo: " + promoCode);
    }

    function openPromotionUrl(url) {
        window.open(url);
    }

    function animateValue(id, start, end, duration) {
        var current = start;
        var increment = end > start ? 1 : -1;
        var obj = document.getElementById(id);
        var stepTime = Math.abs(Math.floor(duration / (end - start)));
        var timer = setInterval(function () {
            current += increment;
            obj.textContent = current;
            if (current == end) {
                clearInterval(timer);
            }
        }, stepTime);
    }

    var reductionAmount = <?php echo $pourcentagereduction; ?>;
    var initialValue = 0;
    var finalValue = <?php echo $pourcentagereduction; ?>;

    animateValue("pourcentagereduction<?php echo $identifiant; ?>", initialValue, finalValue, 2000);
</script>","custom_css":"
