#include <gtest/gtest.h>

class ArrayTest : public testing::Test {
 protected:
    Array* arr;
    ArrayTest() {}
    ~ArrayTest() override {}
    void SetUp() override {
        arr = new Array(10, 2, 30);
    }
    void TearDown() override {
        delete arr;
    }
};

using ArrayDeathTest = ArrayTest;

TEST_F(ArrayTest, CorrectSizesInitialization) {
    EXPECT_EQ(arr->GetX(), 10);
    EXPECT_EQ(arr->GetY(), 2);
    EXPECT_EQ(arr->GetZ(), 30);
}

TEST_F(ArrayTest, SetAndGetElement) {
    (*arr)[4][1][2] = 100500;
    (*arr)[2][0][4] = 0;
    uint32_t element1 = arr->GetElement(4, 1, 2);
    uint32_t element2 = arr->GetElement(2, 0, 4);

    EXPECT_EQ(element1, 100500);
    EXPECT_EQ(element2, 0);
}

TEST_F(ArrayTest, AssignmentOperator) {
    Array otherArray(10, 2, 30);
    otherArray[1][1][1] = 42;
    otherArray[6][0][16] = 50250;
    *arr = otherArray;

    EXPECT_EQ(arr->GetElement(1, 1, 1), 42);
    EXPECT_EQ(arr->GetElement(6, 0, 16), 50250);
}

TEST_F(ArrayTest, StoreAndGetMaxAndGreater17BitElements) {
    (*arr)[5][0][28] = 131071;
    (*arr)[0][0][25] = 131072;
    (*arr)[8][1][21] = 131075;

    EXPECT_EQ(arr->GetElement(5, 0, 28), 131071);
    EXPECT_EQ(arr->GetElement(0, 0, 25), 0);
    EXPECT_EQ(arr->GetElement(8, 1, 21), 3);
}

TEST_F(ArrayTest, StoreAndGetElementAtBoundaries) {
    (*arr)[0][0][0] = 5;
    (*arr)[9][1][29] = 121069;

    EXPECT_EQ(arr->GetElement(0, 0, 0), 5);
    EXPECT_EQ(arr->GetElement(9, 1, 29), 121069);
}

TEST_F(ArrayDeathTest, StoreElementOutOfRange) {
    EXPECT_EXIT(arr->StoreElement(10, 2, 30, 123), 
                testing::ExitedWithCode(EXIT_FAILURE), 
                "--array size out of range"
    );
    EXPECT_EXIT(arr->StoreElement(14, 1, 39, 0), 
                testing::ExitedWithCode(EXIT_FAILURE), 
                "--array size out of range"
    );
}

TEST_F(ArrayDeathTest, GetElementOutOfRange) {
    EXPECT_EXIT(arr->GetElement(10, 2, 30),
                testing::ExitedWithCode(EXIT_FAILURE),
                "--array size out of range"
    );
    EXPECT_EXIT(arr->GetElement(12, 2, 28),
                testing::ExitedWithCode(EXIT_FAILURE),
                "--array size out of range"
    );
}

TEST_F(ArrayTest, MultiplicationOperator) {
    (*arr)[0][1][1] = 2;
    (*arr)[8][0][13] = 13;
    (*arr)[9][1][0] = 569;
    Array result = (*arr) * 15;

    EXPECT_EQ(result.GetElement(0, 1, 1), 30);
    EXPECT_EQ(result.GetElement(8, 0, 13), 195);
    EXPECT_EQ(result.GetElement(9, 1, 0), 8535);
}

TEST_F(ArrayTest, SubtractionOperator) {
    (*arr)[0][0][0] = 334;
    (*arr)[9][1][29] = 1000;
    Array other(10, 2, 30);
    other[0][0][0] = 4;
    other[9][1][29] = 1;
    Array result = (*arr) - other;

    EXPECT_EQ(result.GetElement(0, 0, 0), 330);
    EXPECT_EQ(result.GetElement(9, 1, 29), 999);
}

TEST_F(DeathArrayTest, SubtractionOperator) {
    (*arr)[0][0][0] = 334;
    (*arr)[9][1][29] = 1000;
    Array other(10, 2, 30);
    other[0][0][0] = 4;
    other[9][1][29] = 1;
    Array result = (*arr) - other;

    EXPECT_EXIT(result,
                testing::ExitedWithCode(EXIT_FAILURE),
                "--array sizes do not match"
    );
}



// Test addition operator between two arrays
TEST_F(ArrayTest, AdditionOperator) {
    arr->StoreElement(0, 0, 0, 5);
    Array other(10, 2, 30);
    other.StoreElement(0, 0, 0, 10);
    Array result = (*arr) + other;
    EXPECT_EQ(result.GetElement(0, 0, 0), 15);
}

// Test stream extraction and insertion operators
TEST_F(ArrayTest, StreamOperator) {
    std::stringstream ss;
    ss << "4 1 2 12345";
    ss >> *arr;
    uint32_t element = arr->GetElement(4, 1, 2);
    EXPECT_EQ(element, 12345);

    ss.str(""); // Clear stringstream
    ss.clear(); // Clear error flags
    ss << *arr;
    std::string output;
    std::getline(ss, output);
    EXPECT_EQ(output, "12345"); // Make sure output format corresponds to operator<< behavior
}

