        cur_root->left = new Node();
        cur_root->left->profit = temp_profit;
        cur_root->left->parent = cur_root;
        cur_root = cur_root->left;
    } else if (temp == 'r') {
        std::cin >> temp_profit;
        cur_root->right = new Node();
        cur_root->right->profit = temp_profit;
        cur_root->right->parent = cur_root;
        cur_root = cur_root->right;
    } else if (temp == 'u') {
        cur_root = cur_root->parent;
    }
}

bool CheckBST(Node* temp, int min, int max) {
    if (temp == nullptr) {
        return true;
    }
    if (temp->profit <= min || max <= temp->profit) {
        return false;
    }
    return CheckBST(temp->left, min, temp->profit) && CheckBST(temp->right, temp->profit, max);
}

int Sum(Node* temp) {
    if (temp == nullptr) {
        return 0;
    }
    int sum_left = Sum(temp->left);
    int sum_right = Sum(temp->right);
    return temp->profit + sum_left + sum_right;
}

int FindMaxSumOfBSTSubtree(Node* temp) {
    if (temp == nullptr) return 0;
    if (CheckBST(temp, INT_MIN, INT_MAX)) {
        // If temp is a valid BST, calculate its sum
        return Sum(temp);
    }
    // Otherwise, recursively find the largest BST sum in the left and right subtrees
    int max_sum_left = FindMaxSumOfBSTSubtree(temp->left);
    int max_sum_right = FindMaxSumOfBSTSubtree(temp->right);
    // Return the maximum sum between left and right subtrees
    return std::max(max_sum_left, max_sum_right);
}

