#include <iostream>
#include <climits>

struct Node {
    Node* left = nullptr;
    Node* right = nullptr;
    Node* parent = nullptr;
    int profit = 0;
    int sum = 0;
    int max;
    int min;

    Node(int prof) : profit(prof), sum(prof), max(profit), min(profit) {}
};

void CreateTree(Node*& cur_root) {
    char temp;
    int temp_profit;
    std::cin >> temp;
    if (temp == 'l') {
        std::cin >> temp_profit;
        cur_root->left = new Node(temp_profit);
        cur_root->left->parent = cur_root;
        cur_root = cur_root->left;
    } else if (temp == 'r') {
        std::cin >> temp_profit;
        cur_root->right = new Node(temp_profit);
        cur_root->right->parent = cur_root;
        cur_root = cur_root->right;
    } else if (temp == 'u') {
        cur_root = cur_root->parent;
    }
}

int max_sum_profit = 0;

void FindMaxSumOfBSTSubtree(Node* temp) {
    if (!temp) return;

    int leftSum = 0, rightSum = 0;
    bool isBST = true;

    if (temp->left) {
        FindMaxSumOfBSTSubtree(temp->left);
        if (temp->left->max < temp->profit) {
            leftSum = temp->left->sum;
        } else {
            isBST = false;
        }
    }

    if (temp->right) {
        FindMaxSumOfBSTSubtree(temp->right);
        if (temp->profit < temp->right->min) {
            rightSum = temp->right->sum;
        } else {
            isBST = false;
        }
    }

    // Update the current node’s min and max if it’s part of a valid BST
    if (isBST) {
        temp->sum = temp->profit + leftSum + rightSum;
        temp->min = temp->left ? temp->left->min : temp->profit;
        temp->max = temp->right ? temp->right->max : temp->profit;
        max_sum_profit = std::max(max_sum_profit, temp->sum);
    } else {
        // Current node is not a BST root, consider max of left or right child sums
        temp->sum = std::max(leftSum, rightSum);
        // Not a BST, hence, no need to update min/max; they stay at initial values
    }
}

int main() {
    int temp_profit;
    std::cin >> temp_profit;
    Node* cur_root = new Node(temp_profit);
    while (cur_root != nullptr) {
        CreateTree(cur_root);
    }
    max_sum_profit = 0;
    FindMaxSumOfBSTSubtree(cur_root);
    std::cout << max_sum_profit << std::endl;

    return 0;
