#include <iostream>

struct Node {
  int data;
  int height;
  int8_t balance;
  Node* left;
  Node* right;
  Node* parent;
};

struct AVL {
  Node* top = nullptr;

int height(Node* root) {
    if (root == nullptr)
      return 0;
    return root->height;
  }

  void UpdateHeightAndBalance(Node* node) {
  if (node == nullptr)
    return;

  node->height = 1 + std::max(height(node->left), height(node->right));
  node->balance = height(node->right) - height(node->left);
  }

  Node* newNode(int value, Node* parent) {
    Node* node = new Node();
    node->data = value;
    node->left = nullptr;
    node->right = nullptr;
    node->parent = parent;
    node->height = 1;
    node->balance = 0;
    return node;
}

  Node* RightRotation(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    x->parent = y->parent;

    if (y->parent != nullptr) {
        if (y->parent->left == y) {
            y->parent->left = x;
        } else {
            y->parent->right = x;
        }
    }

    x->right = y;
    y->parent = x;

    y->left = T2;
    if (T2 != nullptr) {
        T2->parent = y;
    }

    UpdateHeightAndBalance(y);
    UpdateHeightAndBalance(x);

    return x;
}

Node* LeftRotation(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;

    y->parent = x->parent;

    if (x->parent != nullptr) {
        if (x->parent->left == x) {
            x->parent->left = y;
        } else {
            x->parent->right = y;
        }
    }

    y->left = x;
    x->parent = y;

    x->right = T2;
    if (T2 != nullptr) {
        T2->parent = x;
    }

    UpdateHeightAndBalance(x);
    UpdateHeightAndBalance(y);

    return y;
}

Node* BalanceTree(Node* node) {
  if (node == nullptr) return node;

  UpdateHeightAndBalance(node);

  if (node->balance < -1) {
    if (node->left->balance <= 0) {
      return RightRotation(node);
    } else if (node->left->balance > 0) {
      node->left = LeftRotation(node->left);
      return RightRotation(node);
    }
  } else if (node->balance > 1) {
    if (node->right->balance >= 0) {
      return LeftRotation(node);
    } else if (node->right->balance < 0) {
      node->right = RightRotation(node->right);
      return LeftRotation(node);
    }
  }

  return node;
}

  Node* Insert(Node* root, int key, Node* parent) {
    if (root == nullptr) {
        return newNode(key, parent);
    }

    if (key < root->data) {
        root->left = Insert(root->left, key, root);
    } else if (key > root->data) {
        root->right = Insert(root->right, key, root);
    } else {
        return root;
    }

    UpdateHeightAndBalance(root);
    return BalanceTree(root);
}


  Node* minValueNode(Node* node) {
    Node* current = node;
    while (current && current->left != nullptr)
        current = current->left;
    return current;
  }

    Node* Delete(Node* node, int data) {
    if (!node) return node;
    if (data < node->data) {
      node->left = Delete(node->left, data);
    } else if (data > node->data) {
      node->right = Delete(node->right, data);
    } else {
      if (!node->left && !node->right) {
        delete node;
        return nullptr;
      }
      if (!node->left) {
        Node* temp = node->right;
        delete node;
        return temp;
      }
      if (!node->right) {
        Node* temp = node->left;
        delete node;
        return temp;
      }

      Node* curr_par = node;
      Node* curr = node->right;
      while (curr->left) {
        curr_par = curr;
        curr = curr->left;
      }

      if (curr_par != node) {
        curr_par->left = curr->right;
      } else {
        curr_par->right = curr->right;
      }

      node->data = curr->data;
      delete curr;
    }

    UpdateHeightAndBalance(node);
    return BalanceTree(node);
  }

  bool Exists(Node* root, int key) {
    if (root == nullptr) return false;

    if (root->data == key) {
      return true;
    }
    else if (root->data > key) {
      return Exists(root->left, key);
    }
    else {
      return Exists(root->right, key);
    }
  }
};

int main() {
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);
  std::cout.tie(0);
  char cmd;
  AVL tree;
  int n;
  std::cin >> n;
  for (int i = 0; i < n; ++i) {
    std::cin >> cmd;
    if (cmd == 'A') {
      int x;
      std::cin >> x;
      tree.top = tree.Insert(tree.top, x, nullptr);
      std::cout << (tree.top == nullptr? 0 : tree.top->balance);
      if (i < n - 1) {
        std::cout << '\n';
      }
    } else if (cmd == 'D') {
      int x;
      std::cin >> x;
      tree.top = tree.Delete(tree.top, x);
      std::cout << (tree.top == nullptr? 0 : tree.top->balance);
      if (i < n - 1) {
        std::cout << '\n';
      }
    } else if (cmd == 'C') {
      int x;
      std::cin >> x;
      tree.Exists(tree.top, x) ? std::cout << 'Y' : std::cout << 'N';
      if (i < n - 1) {
        std::cout << '\n';
      }
    }
  }
}


