class DataGenerator(Sequence):
    def __init__(self, filename, batch_size, n_classes, shuffle=False):
        self.filename = filename
        self.batch_size = batch_size
        self.n_classes = n_classes
        self.shuffle = shuffle
        self.data = self._load_data()  # Load and process data on initialization
        self.on_epoch_end()

    def _load_data(self):
        director_data, loganov_data = [], []
        with open(self.filename, 'r', encoding='utf-8') as file:
            for line in file:
                data = json.loads(line)
                if 'director\\TestoedovNA' in data['SourceHostname_User']:
                    director_data.append(data)
                elif data['SourceHostname_User'] == 'n764265.iss-reshetnev.ru':
                    loganov_data.append(data)
        return {
            'director\\TestoedovNA': director_data,
            'n764265.iss-reshetnev.ru': loganov_data
        }

    def on_epoch_end(self):
        if self.shuffle:
            np.random.shuffle(self.data['director\\TestoedovNA'])
            np.random.shuffle(self.data['n764265.iss-reshetnev.ru'])

    def __len__(self):
        return min(len(self.data['director\\TestoedovNA']), len(self.data['n764265.iss-reshetnev.ru'])) // (self.batch_size // 2)

    def __getitem__(self, index):
        x = np.zeros((self.batch_size, 100, 3))
        y = np.zeros((self.batch_size), dtype=int)

        half_batch = self.batch_size // 2
        director_index = index * half_batch
        loganov_index = index * half_batch
        for i in range(half_batch):
            data = self.data['director\\TestoedovNA'][director_index + i]
            x[i] = np.array([data['EventId'], data['ThreadId'], data['Image']])[:100]
            y[i] = data['Class']

            data = self.data['n764265.iss-reshetnev.ru'][loganov_index + i]
            x[i + half_batch] = np.array([data['EventId'], data['ThreadId'], data['Image']])[:100]
            y[i + half_batch] = data['Class']

        return x, tf.keras.utils.to_categorical(y, num_classes=self.n_classes)


