def scroll(es_obj, _scroll_id, scroll_time='5m'): 
    while True:
        res = es_obj.scroll(scroll_id=_scroll_id, scroll=scroll_time)
        _scroll_id = res['_scroll_id']
        hits = res['hits']['hits']
        if len(hits) == 0: 
            break
        yield from hits

keep_running = True

def check_input():
