function validateEmail(email) {
	const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
	return emailRegex.test(email);
}

// Function to validate credit card number (12 digits)
function validateCreditCardNumber(cardNumber) {
    // Check if the cardNumber is a string of exactly 12 characters
    const cardNumberRegex = /^.{12}$/;

    return cardNumberRegex.test(cardNumber);
}

app.post("/api/customers/", (req, res, next) => {
	try {
		var errors = [];

		if (!req.body) {
			errors.push("Invalid input");
			res.status(400).json({ "error": errors });
			return;
		}

		const {
			firstName,
			lastName,
			email,
			phone,
			address,
			createdDate
		} = req.body;

		// Validation
		if (!validateEmail(email)) {
			errors.push("Invalid email address");
		}

		if (!validateCreditCardNumber(phone)) {
			errors.push("Invalid credit card number (12 digits)");
		}

		if (errors.length > 0) {
			res.status(400).json({ "error": errors });
			return;
		}

		var sql = 'INSERT INTO customer (firstName, lastName, email, phone, address, createdDate) VALUES (?,?,?,?,?,?)';
		var params = [firstName, lastName, email, phone, address, createdDate];

		db.run(sql, params, function (err, result) {
			if (err) {
				res.status(400).json({ "error": err.message });
				return;
			} else {
				console.log('Customer registered');
				res.status(201).json({
					"message": `Customer ${firstName + lastName} registered successfully`,
					"data": req.body,
					"id": this.lastID
				});
			}
		});
	} catch (E) {
		console.log(E);
		res.status(400).send(E);
	}
});

